#!/usr/bin/env python3
"""Batch 3 page builder (Water Advisor, 2026-11-05, Skitch's 596: pages 9 to 12 of the frozen DBP page list v1.0):
dbp.monitoring.routine, dbp.monitoring.reduced-increased, dbp.applicability.stage2, dbp.precursors.toc. Same method as
Batches 1 and 2 (tools/page_builder.py): every quote an exact, unique substring of the normalized 2026-07-01 eCFR
capture; a scope span on every claim; conditions say what the quotes condition. The D2 fold-in claims (141.622 into
page 9; 141.627 and 141.628 into page 10; 141.130 into page 11) carry the claim ids the frozen list planned. Page 9 also
quotes 141.132(b)(1)(i), (b)(2), (b)(3) and (c) so that the routine-monitoring page carries the subpart L (Stage 1)
locations and the residual and byproduct monitoring the question bank expects there; those anchors are beyond the
frozen list's 141.621 and 141.622 for page 9 and are flagged in the commit for Skitch. Page 12 carries the corpus's
first table claim (the Step 1 TOC removal table). Rebuilding rewrites the four pages with fresh timestamps."""
from page_builder import quote, claim, page

def claim_table(page_id, name, subject, operator, metric, table_value, quotes, applicability, conditions=(), exceptions=()):
    return {"claim_id": f"claim.{page_id}.{name}", "kind": "table", "subject": subject,
            "relation": {"operator": operator, "regulatory_metric": metric}, "table_value": table_value,
            "conditions": list(conditions), "exceptions": list(exceptions), "jurisdiction": "US-federal",
            "applicability": applicability, "supporting_quote_ids": [f"quote.{page_id}.{q}" for q in dict.fromkeys(quotes)]}

