      quote(pid, "remain-reduced", "141.623", S623_B), quote(pid, "resume-routine", "141.623", S623_C), quote(pid, "state-discretion", "141.623", S623_D),
      quote(pid, "increased-monitoring-trigger", "141.625", S625_A), quote(pid, "violation", "141.625", S625_B), quote(pid, "return-to-routine", "141.625", S625_C),
